sys_variable_value.value:
(function execute(inputs, outputs) {
    var ESCROW    = 'x_2210852_odee_s_0_odee_ticket';
    var CLIENT_ID = 'SERVICENOW';

    var PENDING = 'pending', UPDATE_PENDING = 'update_pending', SYNCED = 'synced', FAILED = 'failed';

    var map = new OD_Map();
    var api = new OD_Auth();

    var g = new GlideRecord(ESCROW);
    if (!g.get(inputs.escrow_sys_id)) {
        outputs.status  = 'ERROR';
        outputs.message = 'Escrow record not found: ' + inputs.escrow_sys_id;
        return;
    }

    var inc      = g.u_incident.getRefRecord();
    var isCreate = (g.u_sync_state == PENDING);
    var isUpdate = (g.u_sync_state == UPDATE_PENDING);

    if(!(isCreate || isUpdate)) return;
    
    try {
        var payload = isCreate ? buildPost() : buildPut();
        outputs.debugpayload = JSON.stringify(payload);
        var res     = api.call(isCreate ? 'POST' : 'PUT', '/ticket', [payload]);
        outputs.debugresponse = JSON.stringify(res);
        var entry   = (res && res.data && res.data[0]) ? res.data[0] : null;
        if (!entry) throw 'OpenData returned no data element.';

        var info   = entry.statusInfo || {};
        var status = info.status || 'ERROR';
        outputs.status  = status;
        outputs.message = info.message || '';

        // HTTP was 200 either way. The per-record verdict lives here.
        if (status === 'ERROR') { markFailed(info.message || 'Unknown error.'); return; }

        // WARNING means "duplicate, not inserted" — OpenData already holds it,
        // but echoes back a null internalTicketId, so recover it with a GET.
        var id = entry.internalTicketId;
        if (!id && status === 'WARNING') id = recoverId(g.u_external_ticket_id.toString());

        markSynced(entry, id);

    } catch (e) {
        outputs.status  = 'ERROR';
        outputs.message = String(e);
        markFailed(String(e));
    }

    // ---------------------------------------------------------------

    function buildPost() {
        var subject = g.short_description.toString() || 'ServiceNow incident ' + g.u_external_ticket_id;
        var body    = g.description.toString() || subject;

        return {
            externalTicketId : g.u_external_ticket_id.toString(),
            clientId         : CLIENT_ID,
            clientName       : 'ServiceNow ITSM',
            typeId           : 1,                                    // Helpdesk
            urgencyLevelId   : 20,
            subject          : subject.substr(0, 255),                  // hard cap in OpenData
            description      : body.substr(0, 19000),                 // body caps at 20000
            originationDate  : map.toDTZ(inc.opened_at) || map.toDTZ(new GlideDateTime()),
            dueDate          : map.toDTZ(inc.due_date),
            location         : scrub(inc.location.getDisplayValue()).substr(0, 255),
            contactName      : inc.caller_id.getDisplayValue(),
            category         : inc.category.toString(),
            workDescription  : 'Created from ServiceNow incident ' + g.u_external_ticket_id + '.'
        };
    }

    function buildPut() {
        var p = { externalTicketId: g.u_external_ticket_id.toString() };

        // Status ONLY when the incident genuinely differs from the mirror.
        // Sending it unconditionally would flatten 110 or 903 back to 100/900.
        var incState = parseInt(inc.state, 10);
        var mirrored = parseInt(g.u_od_state, 10);
        if (!isNaN(incState) && incState !== mirrored) {
            var sid = map.stateToCanonicalStatusId(incState, inc.close_code.toString());
            if (sid) p.statusId = sid;                      // never 1000; see OpenDataMap
        }

        // Omitted fields keep OpenData's current values — that is the whole
        // point of the merge semantics. Do not pad this object out.
        return p;
    }

    function recoverId(externalId) {
        try {
            var r = api.call('GET', '/ticket?externalTicketId=' + encodeURIComponent(externalId), null);
            return (r && r.data && r.data[0]) ? r.data[0].internalTicketId : null;
        } catch (e) { return null; }
    }

    function markSynced(entry, id) {
        const status_map_snow_odee = {
            1: 'new',
            2: 'in_progress',
            3: 'on_hold',
            6: 'resolved',
            7: 'closed',
            8: 'canceled'
        };

        const status_map_odee_snow = {
            'new': 1,
            'in_progress': 2,
            'on_hold': 3,
            'resolved': 6,
            'closed': 7,
            'canceled': 8
        };
        if (id) {
            g.correlation_id      = String(id);
            g.correlation_display = 'Modius OpenData';
        }
        // Snapshot from the RESPONSE, never from what we sent: PUT echoes back
        // the ticket's current values even for fields we omitted.
        if (entry.statusId != null) {
            g.u_od_status_id = entry.statusId;
            g.u_od_state     = status_map_snow_odee[map.statusIdToState(entry.statusId)];
        }
        if (entry.urgencyLevelId != null) g.u_od_urgency_id = entry.urgencyLevelId;

        // A POST always lands as New (1). If ServiceNow is already further
        // along, queue the corrective PUT rather than declaring victory.
        var needsCorrection = isCreate
            && !isNaN(parseInt(inc.state, 10))
            && parseInt(inc.state, 10) !== map.statusIdToState(entry.statusId);

        g.u_sync_state   = needsCorrection ? UPDATE_PENDING : SYNCED;
        g.u_direction    = 'outbound';
        g.u_last_error   = '';
        g.u_attempts     = 0;
        g.u_last_attempt = new GlideDateTime();
        g.active         = !(g.u_sync_state == SYNCED && map.isTerminal(g.u_od_status_id));
        g.update();
    }

    function markFailed(msg) {
        g.u_sync_state   = FAILED;
        g.u_last_error   = String(msg).substr(0, 4000);
        g.u_attempts     = (parseInt(g.u_attempts, 10) || 0) + 1;
        g.u_last_attempt = new GlideDateTime();
        g.update();
        // u_od_* and u_od_state are left alone — they still describe OpenData.
    }

    // OpenData rejects angle brackets in the client fields and stores the
    // rest as free text, so strip markup rather than escaping it.
    function scrub(v) {
        return String(v || '').replace(/[<>]/g, '');
    }

})(inputs, outputs);

